    rows={r for r,c in zeros}; cols={c for r,c in zeros}
    vertical=len(rows)>len(cols)
    path_cols={c for c in cols if sum(grid[r][c]==0 for r in range(h))>3}
    path_rows={r for r in rows if sum(grid[r][c]==0 for c in range(w))>3}
    for r in range(h):
        for c in range(w):
            if grid[r][c]==9 and ((vertical and c not in path_cols) or (not vertical and r not in path_rows)):
                out[r][c]=9
    if vertical:
        top=sum(r<3 for r,c in zeros); bottom=sum(r>=h-3 for r,c in zeros)
        src=list(range(3)) if top>bottom else list(range(h-3,h))
        dst=list(range(h-3,h)) if top>bottom else list(range(3))
        for sr,dr in zip(src,dst):
            for c in range(w):
                if grid[sr][c]==0 or c in path_cols:
                    out[dr][c]=grid[sr][c]
    else:
        left=sum(c<3 for r,c in zeros); right=sum(c>=w-3 for r,c in zeros)
        src=list(range(3)) if left>right else list(range(w-3,w))
        dst=list(range(w-3,w)) if left>right else list(range(3))
        for sc,dc in zip(src,dst):
            for r in range(h):
                if grid[r][sc]==0 or r in path_rows:
                    out[r][dc]=grid[r][sc]
    return out
'''
